func readV22(r *nino.Reader) []*string {
	v := nino.ReadSlice(r, 1, (*nino.Reader).StringPtr)
	if v == nil {
		return nil
	}
	seen := make(map[string]struct{}, len(v))
	null := false
	for _, s := range v {
		dup := false
		if s == nil {
			dup, null = null, true
		} else if _, dup = seen[*s]; !dup {
			seen[*s] = struct{}{}
		}
		if dup {
			r.Fail(nino.CodeDuplicateKey, "")
			return nil
		}
	}
	return v
}

